import { Avatar, BotAvatar } from '../ui/Avatar';
import { useSelector } from 'react-redux';
import { selectUser } from '../../store/slices/authSlice';
import { useTheme } from '../../hooks/useTheme';
import { formatTime } from '../../utils/helpers';

export default function MessageBubble({ message }) {
  const user = useSelector(selectUser);
  const { textHex, mutedHex, msgBotHex } = useTheme();
  const isUser = message.role === 'user';

  return (
    <div style={{
      display: 'flex', gap: 12, padding: '8px 20px',
      flexDirection: isUser ? 'row-reverse' : 'row',
      alignItems: 'flex-start', animation: 'fadeUp 0.2s ease',
    }}>
      {isUser ? <Avatar name={user?.name ?? 'You'}/> : <BotAvatar/>}
      <div style={{ maxWidth: '72%', display: 'flex', flexDirection: 'column', gap: 4, alignItems: isUser ? 'flex-end' : 'flex-start' }}>
        {/* Attachment chips */}
        {message.attachments?.map((a, i) => (
          <div key={i} style={{
            display: 'inline-flex', alignItems: 'center', gap: 6,
            background: msgBotHex, borderRadius: 8,
            padding: '5px 10px', fontSize: 12.5, color: textHex, marginBottom: 2,
          }}>
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#6366f1" strokeWidth="2"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>
            {a.name}
          </div>
        ))}
        {/* Bubble */}
        <div style={{
          padding: '10px 14px',
          borderRadius: isUser ? '16px 16px 4px 16px' : '16px 16px 16px 4px',
          background: isUser ? 'linear-gradient(135deg,#6366f1,#8b5cf6)' : msgBotHex,
          color: isUser ? '#fff' : textHex,
          fontSize: 14.5, lineHeight: 1.65, whiteSpace: 'pre-wrap', wordBreak: 'break-word',
        }}>
          {message.content}
        </div>
        <span style={{ fontSize: 11.5, color: mutedHex }}>{formatTime(message.ts)}</span>
      </div>
    </div>
  );
}
